"""validator-69e71b (TASK-20260923-69e71b): own finite-field, polynomial and
linear-algebra code for the J1/J2 recomputations.

Pure Python 3.11 standard library only. Written from scratch for this review;
imports nothing from experiments/EXP-FROB-ec08b5/impl/ and no Sage.

Representations
  BaseField(q)   F_q for q prime, q = 4 (F_2[w]/(w^2+w+1)), q = 9 (F_3[w]/(w^2+1));
                 elements are ints 0..q-1 (a0 + p*a1 for q = p^2), with full
                 add/mul tables checked against the field axioms at construction.
  Ext(F, g)      F_{q^n} = F_q[x]/(g), g monic irreducible over F_q of degree n
                 (irreducibility re-checked by brute-force trial division);
                 elements are n-tuples over F_q in the power basis 1, x, ..., x^(n-1).
  GF2n(g)        F_{2^n} as ints (bit i = coeff of x^i), g an irreducible int,
                 for the q = 2 cells where speed matters.
"""
from itertools import combinations, product


# ----------------------------------------------------------------- base field
class BaseField:
    def __init__(self, q):
        self.q = q
        if q in (4, 9):
            p = 2 if q == 4 else 3

            def enc(a0, a1):
                return (a0 % p) + p * (a1 % p)

            def dec(z):
                return z % p, z // p

            def add(x, y):
                a0, a1 = dec(x)
                b0, b1 = dec(y)
                return enc(a0 + b0, a1 + b1)

            def mul(x, y):
                a0, a1 = dec(x)
                b0, b1 = dec(y)
                c0, c1, c2 = a0 * b0, a0 * b1 + a1 * b0, a1 * b1
                if q == 4:                      # w^2 = w + 1
                    return enc(c0 + c2, c1 + c2)
                return enc(c0 - c2, c1)         # q == 9: w^2 = -1
        else:
            if q < 2 or any(q % d == 0 for d in range(2, q)):
                raise ValueError("q must be prime, 4 or 9")
            p = q

            def add(x, y):
                return (x + y) % q

            def mul(x, y):
                return (x * y) % q
        self.p = p
        R = range(q)
        self.A = [[add(x, y) for y in R] for x in R]
        self.M = [[mul(x, y) for y in R] for x in R]
        self.neg = [next(y for y in R if self.A[x][y] == 0) for x in R]
        self.inv = [None] + [next(y for y in R if self.M[x][y] == 1) for x in range(1, q)]
        self.S = [[self.A[x][self.neg[y]] for y in R] for x in R]
        self._check_axioms()

    def _check_axioms(self):
        q, A, M = self.q, self.A, self.M
        R = range(q)
        for x in R:
            assert A[x][0] == x and M[x][1] == x and M[x][0] == 0
            for y in R:
                assert A[x][y] == A[y][x] and M[x][y] == M[y][x]
                for z in R:
                    assert A[A[x][y]][z] == A[x][A[y][z]]
                    assert M[M[x][y]][z] == M[x][M[y][z]]
                    assert M[x][A[y][z]] == A[M[x][y]][M[x][z]]
        for x in range(1, q):
            assert self.inv[x] is not None


# ---------------------------------------------------------------- polynomials
def ptrim(a):
    a = list(a)
    while a and a[-1] == 0:
        a.pop()
    return a


def padd(F, a, b):
    n = max(len(a), len(b))
    a = list(a) + [0] * (n - len(a))
    b = list(b) + [0] * (n - len(b))
    return ptrim(F.A[x][y] for x, y in zip(a, b))


def psub(F, a, b):
    n = max(len(a), len(b))
    a = list(a) + [0] * (n - len(a))
    b = list(b) + [0] * (n - len(b))
    return ptrim(F.S[x][y] for x, y in zip(a, b))


def pmul(F, a, b):
    a, b = ptrim(a), ptrim(b)
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                if y:
                    out[i + j] = F.A[out[i + j]][F.M[x][y]]
    return ptrim(out)


def pdivmod(F, a, b):
    a, b = ptrim(a), ptrim(b)
    assert b, "division by zero polynomial"
    inv_lc = F.inv[b[-1]]
    quo = [0] * max(len(a) - len(b) + 1, 0)
    r = a[:]
    while len(r) >= len(b) and r:
        c = F.M[r[-1]][inv_lc]
        s = len(r) - len(b)
        quo[s] = c
        for i, bi in enumerate(b):
            r[s + i] = F.S[r[s + i]][F.M[c][bi]]
        r = ptrim(r)
    return ptrim(quo), r


def monic_polys(F, d):
    """All monic polynomials of degree exactly d, low-to-high coefficient lists."""
    for coeffs in product(range(F.q), repeat=d):
        yield list(coeffs) + [1]


def is_irreducible(F, g):
    """Brute force: no monic factor of degree 1..deg(g)//2."""
    g = ptrim(g)
    d = len(g) - 1
    if d <= 0:
        return False
    for k in range(1, d // 2 + 1):
        for h in monic_polys(F, k):
            if not pdivmod(F, g, h)[1]:
                return False
    return True


def first_irreducible(F, n):
    for g in monic_polys(F, n):
        if g[0] != 0 and is_irreducible(F, g):
            return g
    raise ValueError("no irreducible found")


def t_n_minus_1(F, n):
    return [F.neg[1]] + [0] * (n - 1) + [1]


def monic_divisors_of(F, f):
    """Brute force: every monic polynomial of degree 0..deg f that divides f."""
    f = ptrim(f)
    out = []
    for d in range(len(f)):
        for h in monic_polys(F, d):
            if not pdivmod(F, f, h)[1]:
                out.append(tuple(h))
    return out


def factor_with_multiplicity(F, f):
    """Irreducible monic factorisation by brute-force trial division."""
    f = ptrim(f)
    lc_inv = F.inv[f[-1]]
    f = [F.M[c][lc_inv] for c in f]
    fac = {}
    d = 1
    while len(f) > 1:
        found = False
        for h in monic_polys(F, d):
            if not is_irreducible(F, h):
                continue
            while True:
                qq, r = pdivmod(F, f, h)
                if r:
                    break
                fac[tuple(h)] = fac.get(tuple(h), 0) + 1
                f = qq
                found = True
            if len(f) == 1:
                break
        d += 1
        if d > 64:
            raise RuntimeError("factorisation did not terminate")
    return fac


# ------------------------------------------------------ extension F_q[x]/(g)
class Ext:
    def __init__(self, F, g):
        g = ptrim(g)
        assert g[-1] == 1 and is_irreducible(F, g), "modulus must be monic irreducible"
        self.F, self.g, self.n, self.q = F, list(g), len(g) - 1, F.q
        n = self.n
        self.zero = (0,) * n
        self.one = (1,) + (0,) * (n - 1)
        self.red = []
        for k in range(2 * n - 1):
            r = pdivmod(F, [0] * k + [1], g)[1]
            self.red.append(tuple(list(r) + [0] * (n - len(r))))
        self.size = self.q ** n

    def const(self, c):
        return (c,) + (0,) * (self.n - 1)

    def add(self, a, b):
        A = self.F.A
        return tuple(A[x][y] for x, y in zip(a, b))

    def sub(self, a, b):
        S = self.F.S
        return tuple(S[x][y] for x, y in zip(a, b))

    def neg(self, a):
        N = self.F.neg
        return tuple(N[x] for x in a)

    def smul(self, c, a):
        Mc = self.F.M[c]
        return tuple(Mc[x] for x in a)

    def mul(self, a, b):
        A, M, n = self.F.A, self.F.M, self.n
        pr = [0] * (2 * n - 1)
        for i, x in enumerate(a):
            if x:
                Mx = M[x]
                for j, y in enumerate(b):
                    if y:
                        pr[i + j] = A[pr[i + j]][Mx[y]]
        out = [0] * n
        for k, c in enumerate(pr):
            if c:
                Mc = M[c]
                rk = self.red[k]
                for i in range(n):
                    if rk[i]:
                        out[i] = A[out[i]][Mc[rk[i]]]
        return tuple(out)

    def pow(self, a, e):
        r, b = self.one, a
        while e:
            if e & 1:
                r = self.mul(r, b)
            b = self.mul(b, b)
            e >>= 1
        return r

    def frob(self, a):
        return self.pow(a, self.q)

    def inv(self, a):
        assert any(a)
        return self.pow(a, self.size - 2)

    def elements(self):
        for t in product(range(self.q), repeat=self.n):
            yield tuple(t)

    def in_base(self, a):
        return all(c == 0 for c in a[1:])


# ------------------------------------------------------------- GF(2^n) as ints
class GF2n:
    def __init__(self, g_int):
        self.g = g_int
        self.n = g_int.bit_length() - 1
        self.size = 1 << self.n
        self.q = 2

    def mul(self, a, b):
        n, g = self.n, self.g
        r = 0
        while b:
            if b & 1:
                r ^= a
            b >>= 1
            a <<= 1
            if a >> n & 1:
                a ^= g
        return r

    def sq(self, a):
        return self.mul(a, a)

    def pow(self, a, e):
        r = 1
        while e:
            if e & 1:
                r = self.mul(r, a)
            a = self.mul(a, a)
            e >>= 1
        return r

    def inv(self, a):
        assert a
        return self.pow(a, self.size - 2)

    def trace(self, a):          # absolute trace to F_2
        t, x = 0, a
        for _ in range(self.n):
            t ^= x
            x = self.sq(x)
        assert t in (0, 1)
        return t

    def half_trace(self, c):     # n odd: z with z^2 + z = c when Tr(c) = 0
        assert self.n % 2 == 1
        z, x = 0, c
        for _ in range((self.n - 1) // 2 + 1):
            z ^= x
            x = self.sq(self.sq(x))
        return z


def gf2_poly_to_int(g):
    return sum(1 << i for i, c in enumerate(g) if c)


# ------------------------------------------------------- linear algebra over F
def rref(F, rows):
    """Canonical reduced row echelon form (tuple of tuples) of the row span."""
    rows = [list(r) for r in rows]
    if not rows:
        return ()
    ncol = len(rows[0])
    piv_row = 0
    for col in range(ncol):
        pr = next((i for i in range(piv_row, len(rows)) if rows[i][col]), None)
        if pr is None:
            continue
        rows[piv_row], rows[pr] = rows[pr], rows[piv_row]
        inv = F.inv[rows[piv_row][col]]
        rows[piv_row] = [F.M[inv][x] for x in rows[piv_row]]
        for i in range(len(rows)):
            if i != piv_row and rows[i][col]:
                c = rows[i][col]
                rows[i] = [F.S[x][F.M[c][y]] for x, y in zip(rows[i], rows[piv_row])]
        piv_row += 1
        if piv_row == len(rows):
            break
    return tuple(tuple(r) for r in rows[:piv_row] if any(r))


def reduce_vec(F, v, B):
    """Residual of v against an rref basis B."""
    v = list(v)
    for b in B:
        col = next(i for i, x in enumerate(b) if x)
        c = v[col]
        if c:
            v = [F.S[x][F.M[c][y]] for x, y in zip(v, b)]
    return tuple(v)


def in_span(F, v, B):
    return not any(reduce_vec(F, v, B))


def span_elements(F, B, n):
    if not B:
        yield (0,) * n
        return
    for coeffs in product(range(F.q), repeat=len(B)):
        v = [0] * n
        for c, b in zip(coeffs, B):
            if c:
                v = [F.A[x][F.M[c][y]] for x, y in zip(v, b)]
        yield tuple(v)


def all_rref_subspaces(F, n, k):
    """Every k-dimensional subspace of F^n, as its canonical rref (direct generation)."""
    q = F.q
    for piv in combinations(range(n), k):
        free = []
        for r, pc in enumerate(piv):
            for c in range(pc + 1, n):
                if c not in piv:
                    free.append((r, c))
        for vals in product(range(q), repeat=len(free)):
            M = [[0] * n for _ in range(k)]
            for r, pc in enumerate(piv):
                M[r][pc] = 1
            for (r, c), v in zip(free, vals):
                M[r][c] = v
            yield tuple(tuple(row) for row in M)


def gaussian_binomial(n, k, q):
    num = den = 1
    for i in range(k):
        num *= q ** (n - i) - 1
        den *= q ** (i + 1) - 1
    return num // den

scripts.j2_curves.py:
"""validator-69e71b J2: recompute every curve-panel row of RUN-FROB-627924 with
own code (ff.py), independently of Sage and of the producer's impl/.

Per (q, n, dim) cell:
  * own field F_q[x]/(g) with g the lexicographically first monic irreducible;
  * every sigma-stable subspace of dimension dim (sum-closure, j1_lattice.py);
  * per recorded curve (a-invariants read from curve_panel.json): all affine points
    over the whole field (group order = 1 + #affine), the factor base F_V for EACH
    candidate V, pi(x, y) = (x^q, y^q), pi-stability by membership, the orbit
    partition by iteration, and f computed THREE ways, none from the orbits:
      f_coord   = #{P in F_V : x^q = x and y^q = y}
      f_Fq_enum = #{(x, y) in F_q x F_q on E : x in V}   (enumerated over F_q only)
      f_orbit   = number of length-1 orbits (reported only for comparison)
  * the #E(F_{q^n}) cross-check by the trace recurrence from #E(F_q).
Controls, own code:
  * EVERY F_q-subspace V' of dimension dim that is NOT sigma-stable: is F_{V'}
    pi-stable (the control would then PASS)? and the same-size subcase.
  * the producer's null-curve model family over F_{q^n} with j^q != j: is F_V
    pi-stable on it? Exhaustive where cheap, seeded sample otherwise.
"""
import json
import random
import sys
import time
from collections import Counter

from ff import (BaseField, Ext, GF2n, all_rref_subspaces, first_irreducible, gf2_poly_to_int,
                in_span, rref, span_elements)
from j1_lattice import stable_by_sum_closure

REPO = "/home/user/crypto-autoresearcher"
CP = json.load(open(f"{REPO}/experiments/EXP-FROB-ec08b5/runs/RUN-FROB-627924/checkpoint/curve_panel.json"))
ROWS = CP["result"]["cells"]
CELLS = [(2, 5, 4), (2, 7, 3), (2, 7, 4), (2, 7, 6), (3, 5, 4), (5, 3, 2), (2, 11, 10), (3, 7, 6), (4, 3, 2), (2, 13, 12)]
RNG = random.Random(6969)
NULL_SAMPLE = {(2, 11): 1500, (2, 13): 400, (3, 5): 3000, (3, 7): 300, (5, 3): None, (2, 5): None, (2, 7): None, (4, 3): None}


def parse_coef(s, q):
    s = s.replace(" ", "")
    if q == 4:
        return {"0": 0, "1": 1, "b": 2, "b+1": 3}[s]      # ff.BaseField(4): w <-> 2, w+1 <-> 3
    return int(s) % q


class Cell:
    def __init__(self, q, n):
        self.q, self.n = q, n
        self.F = BaseField(q)
        self.g = first_irreducible(self.F, n)
        self.E = Ext(self.F, self.g)
        self.els = list(self.E.elements())
        self.idx = {e: i for i, e in enumerate(self.els)}
        self.N = len(self.els)
        self.gf2 = GF2n(gf2_poly_to_int(self.g)) if q == 2 else None
        if self.gf2:
            self.to_int = [sum(b << i for i, b in enumerate(e)) for e in self.els]
            self.from_int = {v: i for i, v in enumerate(self.to_int)}
            G = self.gf2
            self.sq = [self.from_int[G.sq(self.to_int[i])] for i in range(self.N)]
            self.frob = self.sq
        else:
            self.frob = [self.idx[self.E.frob(e)] for e in self.els]
        self.base = [i for i in range(self.N) if self.frob[i] == i]         # F_q inside F_{q^n}
        assert len(self.base) == q
        self._mul = {}

    def mul(self, a, b):
        if self.gf2:
            G = self.gf2
            return self.from_int[G.mul(self.to_int[a], self.to_int[b])]
        return self.idx[self.E.mul(self.els[a], self.els[b])]

    def add(self, a, b):
        if self.gf2:
            return self.from_int[self.to_int[a] ^ self.to_int[b]]
        return self.idx[self.E.add(self.els[a], self.els[b])]

    def const(self, c):
        return self.idx[self.E.const(c)]

    def on_curve(self, ai, x, y):
        a1, a2, a3, a4, a6 = ai
        m, ad = self.mul, self.add
        lhs = ad(ad(m(y, y), m(a1, m(x, y))), m(a3, y))
        rhs = ad(ad(ad(m(x, m(x, x)), m(a2, m(x, x))), m(a4, x)), a6)
        return lhs == rhs

    def _gf2_tables(self):
        if hasattr(self, "_T"):
            return self._T
        G = self.gf2
        inv2 = [0] * self.N
        tr = [0] * self.N
        ht = [None] * self.N
        for X in range(self.N):
            if X:
                inv2[X] = G.sq(G.inv(X))
            tr[X] = G.trace(X)
            if tr[X] == 0:
                z = G.half_trace(X)
                assert G.sq(z) ^ z == X
                ht[X] = z
        self._T = (inv2, tr, ht)
        return self._T

    def points_over(self, ai, xs, verify=True):
        """dict x -> [y, ...] of affine points with x in xs (indices)."""
        a1, a2, a3, a4, a6 = ai
        out = {}
        if self.gf2 and a1 == self.const(1) and a3 == 0 and a4 == 0:
            G = self.gf2
            inv2, tr, ht = self._gf2_tables()
            A2, A6 = self.to_int[a2], self.to_int[a6]
            sqrtA6 = G.pow(A6, 1 << (G.n - 1))             # unique square root
            for x in xs:
                X = self.to_int[x]
                if X == 0:
                    ys = [self.from_int[sqrtA6]]
                else:
                    c = X ^ A2 ^ G.mul(A6, inv2[X])
                    if tr[c]:
                        ys = []
                    else:
                        z = ht[c]
                        ys = [self.from_int[G.mul(X, z)], self.from_int[G.mul(X, z ^ 1)]]
                if verify:
                    for y in ys:
                        assert self.on_curve(ai, x, y)
                out[x] = ys
            return out
        if self.q % 2 == 0:                                 # q = 4, a1 = 1, a3 = 0: lhs map y^2 + x y
            assert a1 == self.const(1) and a3 == 0
            if not hasattr(self, "_lhs"):
                self._lhs = {}
            m, ad = self.mul, self.add
            for x in xs:
                if x not in self._lhs:
                    d = {}
                    for y in range(self.N):
                        d.setdefault(ad(m(y, y), m(x, y)), []).append(y)
                    self._lhs[x] = d
                rhs = ad(ad(ad(m(x, m(x, x)), m(a2, m(x, x))), m(a4, x)), a6)
                ys = list(self._lhs[x].get(rhs, []))
                if verify:
                    for y in ys:
                        assert self.on_curve(ai, x, y)
                out[x] = ys
            return out
        # odd characteristic, a1 = a3 = 0: y^2 = rhs
        if not hasattr(self, "_roots"):
            self._roots = {}
            for y in range(self.N):
                self._roots.setdefault(self.mul(y, y), []).append(y)
        m, ad = self.mul, self.add
        for x in xs:
            rhs = ad(ad(ad(m(x, m(x, x)), m(a2, m(x, x))), m(a4, x)), a6)
            out[x] = list(self._roots.get(rhs, []))
        return out


def subspace_members(cell, B):
    return [cell.idx[v] for v in span_elements(cell.F, B, cell.n)]


def measure(cell, ai, pts_by_x, V_members):
    Fb = [(x, y) for x in V_members for y in pts_by_x.get(x, [])]
    S = set(Fb)
    pi = lambda P: (cell.frob[P[0]], cell.frob[P[1]])
    stable = all(pi(P) in S for P in Fb)
    f_coord = sum(1 for (x, y) in Fb if cell.frob[x] == x and cell.frob[y] == y)
    Vset = set(V_members)
    f_Fq_enum = sum(1 for x in cell.base if x in Vset for y in cell.base if cell.on_curve(ai, x, y))
    orbits = None
    if stable:
        seen, orbits = set(), []
        for P in Fb:
            if P in seen:
                continue
            L, Q = 0, P
            while True:
                seen.add(Q)
                L += 1
                Q = pi(Q)
                if Q == P:
                    break
            orbits.append(L)
    n = cell.n
    pred = (f_coord + (len(Fb) - f_coord) // n) if (len(Fb) - f_coord) % n == 0 else None
    return dict(factor_base_size=len(Fb), pi_stable=stable, fixed_points_coord=f_coord,
                fixed_points_Fq_enum=f_Fq_enum,
                fixed_points_from_orbits=(sum(1 for L in orbits if L == 1) if orbits is not None else None),
                measured_orbits=(len(orbits) if orbits is not None else None), predicted_orbits=pred,
                prediction_exact=(orbits is not None and pred == len(orbits)),
                orbit_size_histogram=(dict(sorted(Counter(orbits).items())) if orbits is not None else None))


def group_order_checks(cell, ai_ints, all_pts):
    q, n = cell.q, cell.n
    affine = sum(len(v) for v in all_pts.values())
    order_brute = 1 + affine
    ai = [cell.const(c) for c in ai_ints]
    base_pts = sum(1 for x in cell.base for y in cell.base if cell.on_curve(ai, x, y))
    Nq = 1 + base_pts
    t = q + 1 - Nq
    s_prev, s = 2, t                                  # s_k = alpha^k + beta^k
    for _ in range(n - 1):
        s_prev, s = s, t * s - q * s_prev
    order_recurrence = q ** n + 1 - s
    return dict(order_brute_force=order_brute, order_recurrence=order_recurrence,
                E_Fq_order=Nq, trace_t=t, ordinary=(t % BaseField(q).p != 0))


def _hyperplanes(cell):
    """Yield (member-test, is_sigma_stable) per hyperplane ker(lambda), lambda up to scalar."""
    n, F = cell.n, cell.F
    if cell.gf2:
        for lam in range(1, cell.N):
            yield ("gf2", lam)
    else:
        for B in all_rref_subspaces(F, n, 1):
            yield ("gen", B[0])


def controls_unstable(cell, pts_by_x, dim, stable_keys, ref_sizes):
    n, F = cell.n, cell.F
    lift = {x for x, ys in pts_by_x.items() if ys}
    npts = {x: len(ys) for x, ys in pts_by_x.items()}
    total = nonstable = passes = 0
    same_size = {s: [0, 0] for s in ref_sizes}
    size_hist = Counter()
    if dim == n - 1:
        lift_l = sorted(lift)
        if cell.gf2:
            ti = cell.to_int
            sig_e = [ti[cell.frob[cell.idx[tuple(1 if i == j else 0 for i in range(n))]]] for j in range(n)]
        for kind, lam in _hyperplanes(cell):
            total += 1
            if kind == "gf2":
                mu = sum((((lam & sig_e[j]).bit_count()) & 1) << j for j in range(n))
                if mu == lam:                               # ker(lambda) sigma-stable
                    continue
                inV = [x for x in lift_l if not (lam & ti[x]).bit_count() & 1]
                pstable = all(not (lam & ti[cell.frob[x]]).bit_count() & 1 for x in inV)
            else:
                def dot(v):
                    acc = 0
                    for a, b in zip(lam, v):
                        acc = F.A[acc][F.M[a][b]]
                    return acc
                mem = [i for i in range(cell.N) if dot(cell.els[i]) == 0]
                if all(dot(cell.els[cell.frob[i]]) == 0 for i in mem):
                    continue
                inV = [x for x in mem if x in lift]
                pstable = all(dot(cell.els[cell.frob[x]]) == 0 for x in inV)
            nonstable += 1
            size = sum(npts[x] for x in inV)
            size_hist[size] += 1
            passes += pstable
            if size in same_size:
                same_size[size][0] += 1
                same_size[size][1] += pstable
        return dict(subspaces_of_dim=total, non_stable=nonstable, non_stable_with_pi_stable_factor_base=passes,
                    same_size_as_reference={str(k): dict(count=v[0], pi_stable=v[1]) for k, v in same_size.items()},
                    min_size=min(size_hist) if size_hist else None, max_size=max(size_hist) if size_hist else None,
                    method="hyperplanes ker(lambda), lambda up to scalar")
    for B in all_rref_subspaces(F, n, dim):
        total += 1
        if B in stable_keys:
            continue
        nonstable += 1
        mem = set(subspace_members(cell, B))
        L = [x for x in mem if x in lift]
        size = sum(npts[x] for x in mem)
        size_hist[size] += 1
        pstable = all(cell.frob[x] in mem for x in L)
        passes += pstable
        if size in same_size:
            same_size[size][0] += 1
            same_size[size][1] += pstable
    return dict(subspaces_of_dim=total, non_stable=nonstable, non_stable_with_pi_stable_factor_base=passes,
                same_size_as_reference={str(k): dict(count=v[0], pi_stable=v[1]) for k, v in same_size.items()},
                min_size=min(size_hist) if size_hist else None, max_size=max(size_hist) if size_hist else None)


def null_family(cell):
    q, N = cell.q, cell.N
    one = cell.const(1)
    fam = []
    if q % 2 == 0:
        for a2 in range(N):
            for a6 in range(1, N):
                fam.append((one, a2, 0, 0, a6))
    elif q == 3:
        for a2 in range(1, N):
            for a6 in range(1, N):
                fam.append((0, a2, 0, 0, a6))
    else:
        for a in range(N):
            for b in range(N):
                fam.append((0, 0, 0, a, b))
    return fam


def j_invariant_not_in_Fq(cell, ai):
    a1, a2, a3, a4, a6 = ai
    m, ad = cell.mul, cell.add
    if cell.q % 2 == 0:                 # a1 = 1, a3 = a4 = 0: j = 1/a6
        if a6 == cell.idx[cell.E.zero]:
            return None
        j = cell.idx[cell.E.inv(cell.els[a6])]
    elif cell.q == 3:                   # y^2 = x^3 + a2 x^2 + a6: j = -a2^3/a6
        if a2 == 0 or a6 == 0:
            return None
        num = m(a2, m(a2, a2))
        j = m(cell.idx[cell.E.neg(cell.els[num])], cell.idx[cell.E.inv(cell.els[a6])])
    else:                               # y^2 = x^3 + a x + b, q = 5
        a3_ = m(a4, m(a4, a4))
        c4 = m(cell.const(4), a3_)
        disc = ad(c4, m(cell.const(27 % 5), m(a6, a6)))
        if disc == 0:
            return None
        j = m(m(cell.const(1728 % 5), c4), cell.idx[cell.E.inv(cell.els[disc])])
    return (cell.frob[j] != j, j == 0)


def controls_null(cell, V_members, sample):
    fam = null_family(cell)
    if sample is not None and sample < len(fam):
        fam = RNG.sample(fam, sample)
    tested = passes = 0
    max_pass_size = None
    sizes = Counter()
    for ai in fam:
        chk = j_invariant_not_in_Fq(cell, ai)
        if chk is None or not chk[0] or chk[1]:
            continue                    # singular, j in F_q, or j = 0 (supersingular in char 2, 3, 5)
        tested += 1
        pts = cell.points_over(ai, V_members, verify=False)
        Fb = [(x, y) for x in V_members for y in pts[x]]
        sizes[len(Fb)] += 1
        stable = all(cell.on_curve(ai, cell.frob[x], cell.frob[y]) for (x, y) in Fb)
        if stable:
            passes += 1
            max_pass_size = max(max_pass_size or 0, len(Fb))
    return dict(null_curves_tested=tested, exhaustive=(sample is None), pi_stable_count=passes,
                largest_factor_base_among_pi_stable=max_pass_size,
                smallest_factor_base_seen=min(sizes) if sizes else None)


def main():
    out = []
    for (q, n, dim) in CELLS:
        t0 = time.perf_counter()
        cell = Cell(q, n)
        S, _ = stable_by_sum_closure(cell.E, cell.F)
        stable_keys = set(S)
        cands = sorted([B for B in S if len(B) == dim])
        cand_members = [subspace_members(cell, B) for B in cands]
        rec_rows = [r for r in ROWS if (r["q"], r["n"], r["dim"]) == (q, n, dim)]
        cell_out = dict(q=q, n=n, dim=dim, modulus_low_to_high=cell.g,
                        stable_subspaces_of_dim=len(cands), rows=[])
        for r in rec_rows:
            ai_ints = [parse_coef(s, q) for s in r["curve"]]
            ai = [cell.const(c) for c in ai_ints]
            all_pts = cell.points_over(ai, range(cell.N))
            go = group_order_checks(cell, ai_ints, all_pts)
            per_cand = [measure(cell, ai, all_pts, mem) for mem in cand_members]
            keys = ("factor_base_size", "measured_orbits", "predicted_orbits", "orbit_size_histogram")
            def matches(m):
                return (m["factor_base_size"] == r["factor_base_size"] and m["fixed_points_coord"] == r["fixed_points"]
                        and m["measured_orbits"] == r["measured_orbits"] and m["predicted_orbits"] == r["predicted_orbits"]
                        and {str(k): v for k, v in (m["orbit_size_histogram"] or {}).items()} == r["orbit_size_histogram"]
                        and m["pi_stable"] == r["pi_stable"] and m["prediction_exact"] == r["prediction_exact"])
            row = dict(curve_index=r["curve_index"], curve=r["curve"], j_recorded=r["j_invariant"],
                       group_order_recorded=r["group_order"], **go,
                       group_order_agrees=(go["order_brute_force"] == go["order_recurrence"] == r["group_order"]),
                       candidates=per_cand,
                       matching_candidates=[i for i, m in enumerate(per_cand) if matches(m)],
                       all_candidates_pi_stable=all(m["pi_stable"] for m in per_cand),
                       all_candidates_P4_exact=all(m["prediction_exact"] for m in per_cand),
                       f_three_ways_agree_all_candidates=all(
                           m["fixed_points_coord"] == m["fixed_points_Fq_enum"] == m["fixed_points_from_orbits"]
                           for m in per_cand),
                       recorded_control_unstable_V=r["control_unstable_V"],
                       recorded_control_null_curve=r["control_null_curve"])
            ref_sizes = {r["factor_base_size"], r["control_unstable_V"]["factor_base_size"]}
            row["control_all_nonstable_Vprime"] = controls_unstable(cell, all_pts, dim, stable_keys, ref_sizes)
            ref = row["matching_candidates"][0] if row["matching_candidates"] else 0
            row["control_null_family"] = controls_null(cell, cand_members[ref], NULL_SAMPLE[(q, n)])
            cell_out["rows"].append(row)
            print(q, n, dim, "curve", r["curve_index"], "match", row["matching_candidates"], "of", len(cands),
                  "order", row["group_order_agrees"], "Vprime pass", row["control_all_nonstable_Vprime"]["non_stable_with_pi_stable_factor_base"],
                  "/", row["control_all_nonstable_Vprime"]["non_stable"],
                  "null pass", row["control_null_family"]["pi_stable_count"], "/", row["control_null_family"]["null_curves_tested"],
                  f"{time.perf_counter()-t0:.1f}s", file=sys.stderr, flush=True)
        cell_out["seconds"] = round(time.perf_counter() - t0, 2)
        out.append(cell_out)
    json.dump(dict(cells=out), sys.stdout, indent=1, default=str)


if __name__ == "__main__":
    main()
